// cue_voice_parity.h - THE WEB'S SOUND ENGINE'S DECISIONS, RECORDED, which c/src/cue_voice.c is held to.
//
// Until the web asked the kernel, src/audio/cueAudio.ts and cueSounds.ts made every decision
// cue_voice.c makes, in TypeScript. Before they were deleted they were driven, at 11f752bc5, over the
// strikes below (with the C voice's own generator standing in for Math.random, so both draw the
// same numbers) against a stand-in AudioContext, and what they started was written down here:
// which take, when its file started, at what level and speed, reversed or not, and the strokes
// before it. The script was a throwaway; this file is the record, and is never regenerated.
// c/tests/anim_plan_test.c test_cue_voice_matches_the_web plays the same strikes through cue_strike.
//
// THE TABLE IS FROZEN with the decisions (soundgen's render at 11f752bc5), so a new render of the
// sounds does not move this test; the rules are what it holds.
//
// The corpus, in the order struck (one voice, its state carried through):
//   911 strikes: real games (tests.c test_plan_cues_over_real_games, salt 0, seat 0)
//   68 strikes: /sounds in context, as the board hands them over
//   68 strikes: /sounds in context, as the page strikes them
//   92 strikes: /sounds each cue
//   700 strikes: any strike
// All of them under the shipped mix (PARITY_SHIPPED), and all but the real games again, by a fresh
// voice, under a mix that wanders and is heavier per card (PARITY_WANDERS).
// Times are microseconds from now; the web's level and speed were floats, written in millionths.

